using System.Security.Cryptography;
using System.Text.Json;
using System.Text.Json.Nodes;
using FruitMachineLab.Runtime;

namespace FruitMachineLab.Adders;

// Oracle31: fresh controlled-input natural 59EB occurrence. Each phase is seeded
// from an actual captured MAME frame; no timer/scheduler cadence or expected
// post-state is generated by this test.
public static class AddersFreshToneOccurrenceVerification
{
    private static string FilePath(string evidence)=>Path.Combine(evidence,"collection","fresh-tone-occurrence.json");
    public static int Verify(string evidence)=>VerifyFile(FilePath(evidence));

    private sealed record Frame(string Name,ushort PC,ulong Cycle,ushort S,ushort U,ushort X,ushort Y,byte A,byte B,byte DP,byte CC,byte[] Ram);

    private static Frame ReadFrame(JsonElement element)
    {
        byte[] ram=[];
        if(element.TryGetProperty("ram_hex",out var hexElement)){
            ram=Convert.FromHexString(hexElement.GetString()!);
            if(ram.Length!=0x800)throw new InvalidDataException($"Snapshot {element.GetProperty("name").GetString()} is not 2 KB");
            string actual=Convert.ToHexString(SHA256.HashData(ram));
            if(!actual.Equals(element.GetProperty("ram_sha256").GetString(),StringComparison.OrdinalIgnoreCase))
                throw new InvalidDataException($"Snapshot {element.GetProperty("name").GetString()} hash differs");
        }
        return new(
            element.GetProperty("name").GetString()!,
            Convert.ToUInt16(element.GetProperty("pc").GetString()!,16),
            Convert.ToUInt64(element.GetProperty("cycle").GetString()!,16),
            Convert.ToUInt16(element.GetProperty("s").GetString()!,16),
            Convert.ToUInt16(element.GetProperty("u").GetString()!,16),
            Convert.ToUInt16(element.GetProperty("x").GetString()!,16),
            Convert.ToUInt16(element.GetProperty("y").GetString()!,16),
            Convert.ToByte(element.GetProperty("a").GetString()!,16),
            Convert.ToByte(element.GetProperty("b").GetString()!,16),
            Convert.ToByte(element.GetProperty("dp").GetString()!,16),
            Convert.ToByte(element.GetProperty("cc").GetString()!,16),
            ram);
    }

    private static Frame Find(JsonElement[] frames,string name)
    {
        foreach(var frame in frames)if(frame.GetProperty("name").GetString()==name)return ReadFrame(frame);
        throw new InvalidDataException($"Missing captured frame {name}");
    }

    // The captured host bytes 44/45/46 are inside the saved 2 KB RAM and must
    // already equal the captured before image; a changed fixture host is rejected
    // rather than silently overwriting captured state. 719B is outside that 2 KB
    // save (the raw debugger saves 0000..07FF only), so it is held to the curator's
    // declared sound-enable value 00; no 719B value is invented from the snapshot.
    private static void Host(Machine m,JsonElement host,Frame before,string phase)
    {
        byte Value(string name)=>Convert.ToByte(host.GetProperty(name).GetString()!,16);
        foreach(var (address,name) in new[]{(0x44,"44"),(0x45,"45"),(0x46,"46")}){
            byte value=Value(name);
            if(value!=before.Ram[address])throw new InvalidDataException($"{phase} host {name}: fixture{value:X2}, captured before{before.Ram[address]:X2}");
        }
        byte enable=Value("719B");
        if(enable!=0)throw new InvalidDataException($"{phase} host 719B differs from the captured sound-enable input 00");
        m.Memory[0x44]=Value("44");m.Memory[0x45]=Value("45");m.Memory[0x46]=Value("46");m.Memory[0x719B]=enable;
    }

    // Exact compared ranges, all inclusive:
    //   controls 044..050 (13 bytes; 04D excluded only for cancel below)
    //   full task pool 1A0..27D = six 0x25-byte records starting 1A0,1C5,1EA,
    //     20F,234,259. AddersSoundResetMemory/ValidateTask derive this end; the
    //     last record is 259..27D and 27E begins the channel links.
    //   channel links 27E..283 (all six links, including the final 283)
    //   YM cache 284..2FF (124 bytes)
    // Only cancel 04D is excluded: the captured 5A1C foreground writes it after
    // the native 5C7A cancel, so that byte has an observed other owner. No other
    // byte is dropped; a mismatch in any compared range fails the phase.
    private const int TaskPoolStart=0x1A0,TaskPoolEnd=0x27D;
    private const int ChannelLinkStart=0x27E,ChannelLinkEnd=0x283;
    private const int CacheStart=0x284,CacheEnd=0x2FF;
    private static void CompareRetained(Machine m,byte[] expected,string phase,bool include4D)
    {
        for(int address=0x44;address<=0x50;address++){
            if(!include4D && address==0x4D)continue;
            if(m.Memory[address]!=expected[address])throw new InvalidDataException($"{phase} control {address:X2}: captured{expected[address]:X2}, actual{m.Memory[address]:X2}");
        }
        for(int address=TaskPoolStart;address<=TaskPoolEnd;address++)
            if(m.Memory[address]!=expected[address])throw new InvalidDataException($"{phase} task pool {address:X3}: captured{expected[address]:X2}, actual{m.Memory[address]:X2}");
        for(int address=ChannelLinkStart;address<=ChannelLinkEnd;address++)
            if(m.Memory[address]!=expected[address])throw new InvalidDataException($"{phase} channel link {address:X3}: captured{expected[address]:X2}, actual{m.Memory[address]:X2}");
        for(int address=CacheStart;address<=CacheEnd;address++)
            if(m.Memory[address]!=expected[address])throw new InvalidDataException($"{phase} cache {address:X3}: captured{expected[address]:X2}, actual{m.Memory[address]:X2}");
    }

    // Source/capture continuations. Queue: 59E6 JSR 5C18 -> 59E9. Service:
    // FEC9 JSR 5CD0 -> FECC, also captured at the 5CD0 stack word and FECC PC.
    // Cancel: 5A0D JSR 5C7A -> 5A10, also captured at the 5C7A stack word and
    // the 5A10 foreground marker.
    private const ushort QueueContinuation=0x59E9;
    private const ushort ServiceContinuation=0xFECC;
    private const ushort CancelContinuation=0x5A10;
    private static ushort Continuation(Machine m,Frame caller,ushort expected,string phase)
    {
        ushort actual=m.ReadWord(caller.S);
        if(actual!=expected)throw new InvalidDataException($"{phase} stack return word {actual:X4} differs from {expected:X4}");
        return actual;
    }

    private static int VerifyFile(string path)
    {
        using var doc=JsonDocument.Parse(File.ReadAllText(path));
        var root=doc.RootElement;
        if(root.GetProperty("schema").GetString()!="fresh-tone-occurrence/1")throw new InvalidDataException("Fresh tone schema differs");
        string classification=root.GetProperty("classification").GetString()!;
        if(!classification.StartsWith("controlled replay natural",StringComparison.Ordinal) || classification.Contains("synthetic",StringComparison.OrdinalIgnoreCase))
            throw new InvalidDataException("Fresh tone classification differs");

        var source=root.GetProperty("source");
        void Source(string name,string expected){if(source.GetProperty(name).GetString()!=expected)throw new InvalidDataException($"Fresh tone source {name} differs");}
        Source("rom_sha1","402D1518BB78FDC489B06C2AABC771E5CE151847");
        Source("mame_version","0.281");
        Source("mame_sha256","0FCE5A88DF4F9D9B1FBF1405812C00848036E615993780978D967DA34204CB7A");
        Source("input_lua_sha256","7C664323A5725E9FB294CB201B17B855564AF2E4A500560ED499F1EE45179D0D");
        Source("replay_actions_sha256","4A051DA15264842697879EFF396B34A789F5D80623F9A2E749C244E6A80E721D");
        Source("debug_sha256","87980007509CB3592B0447CE0F2617EA1CB2DA03F68784A427B015DC2DAC6910");
        Source("debugger_sha256","8F702823906F89DAE4B3C2FD690CE0583528C9B486111635954E9FC8667F86B9");
        Source("arguments_sha256","368B8FC9B5D5ED02D34C427BD89467DEE2D852686C2F85939B50443A4258A77C");
        Source("actions_sha256","17E315DAA7C7007856403A9CA2484B7812F8D37411FE14FAA40B77E8DEC77E9A");
        if(source.GetProperty("exit").GetInt32()!=0)throw new InvalidDataException("Fresh tone capture exit differs");
        var historical=root.GetProperty("historical");
        if(historical.GetProperty("retained_entry_x").GetString()!="80A3" ||
           historical.GetProperty("retained_cycle").GetString()!="699661924" ||
           historical.GetProperty("retained_ram_sha256").GetString()!="DF378149DDBE03252E8D19EE4B3CC97AC091E66573F16D521E30B5E1DFE172CC")
            throw new InvalidDataException("Historical retained tone snapshot changed");

        var primary=root.GetProperty("primary");
        if(primary.GetProperty("cycle").GetString()!="0000000003CCB742" || primary.GetProperty("entry_x").GetString()!="8132")
            throw new InvalidDataException("Fresh occurrence identity differs");
        var primaryFrames=primary.GetProperty("frames").EnumerateArray().ToArray();
        var markers=primary.GetProperty("markers").EnumerateArray().ToArray();
        var fc4d=Find(primaryFrames,"fc4d");var queue=Find(primaryFrames,"queue");
        var serviceBefore=Find(primaryFrames,"service-before");var serviceAfter=Find(primaryFrames,"service-after");
        var serviceAfterClear=Find(primaryFrames,"service-after-clear");
        if(primary.GetProperty("ram_sha256").GetString()!="30E97EE9A1A9CC7D50868BDD595D69E52A0A6BF9A0C65E5909F367F8BB3AF6BE" ||
           Convert.ToHexString(SHA256.HashData(fc4d.Ram))!="30E97EE9A1A9CC7D50868BDD595D69E52A0A6BF9A0C65E5909F367F8BB3AF6BE")
            throw new InvalidDataException("Fresh FC4D snapshot differs");
        if(fc4d.PC!=0x00FC || fc4d.Cycle!=0x3CCB742 || fc4d.X!=0x8132 || fc4d.Y!=0xFC4D || fc4d.S!=0x07AA)
            throw new InvalidDataException("Fresh FC4D caller frame differs");
        if(queue.PC!=0x5C18 || queue.Cycle!=0x3CCB7AE || queue.S!=0x0798 || queue.U!=0x0672 || queue.X!=0x59EB || queue.Y!=0xFC4F || queue.A!=0x91 || queue.B!=0x31)
            throw new InvalidDataException("Fresh queue caller frame differs");
        if(serviceBefore.PC!=0x5CD0 || serviceBefore.Cycle!=0x3CCC0FD || serviceBefore.S!=0x078B || serviceBefore.U!=0x0672 || serviceBefore.X!=0x0366 || serviceBefore.Y!=0 || serviceBefore.A!=0x05 || serviceBefore.B!=0x0B)
            throw new InvalidDataException("Fresh service caller frame differs");
        if(serviceAfter.PC!=0xFECC || serviceAfter.Cycle!=0x3CCC5DD || serviceAfter.A!=0x39 || serviceAfter.B!=0x1C)
            throw new InvalidDataException("Fresh service return frame differs");
        if(!serviceAfter.Ram.AsSpan().SequenceEqual(serviceAfterClear.Ram))throw new InvalidDataException("Fresh FECC/FECE snapshots differ");
        var foreground=markers.Where(m=>m.GetProperty("name").GetString() is "foreground-5a14" or "foreground-5a05").ToArray();
        if(foreground.Length!=2)throw new InvalidDataException("Fresh foreground markers differ");
        var p14=ReadFrame(foreground[0]);var p05=ReadFrame(foreground[1]);
        if(p14.Cycle!=0x3CCB76B || p05.Cycle!=0x3CCB8BF || p05.Cycle-p14.Cycle!=340)throw new InvalidDataException("Fresh foreground 5A14-5A05 width differs");
        var p0a=ReadFrame(markers.First(m=>m.GetProperty("name").GetString()=="foreground-5a0a"));
        if(p0a.Cycle!=0x3CE0402 || p0a.Cycle-p05.Cycle!=84803)throw new InvalidDataException("Fresh foreground 5A05-5A0A width differs");
        var cancelMarker=ReadFrame(markers.First(m=>m.GetProperty("name").GetString()=="cancel-entry"));
        if(cancelMarker.PC!=0x5C7A || cancelMarker.Cycle!=0x3CE040D || cancelMarker.S!=0x079E || cancelMarker.A!=0x91 || cancelMarker.B!=0x02)
            throw new InvalidDataException("Fresh cancel caller frame differs");
        var p10=ReadFrame(markers.First(m=>m.GetProperty("name").GetString()=="cancel-foreground-5a10"));
        var p1c=ReadFrame(markers.First(m=>m.GetProperty("name").GetString()=="return-5a1c"));
        if(p10.Cycle!=0x3CE0541 || p1c.Cycle!=0x3CE0550 || p1c.S!=0x07A4)throw new InvalidDataException("Fresh cancel-return foreground markers differ");
        var commands=primary.GetProperty("commands").EnumerateArray().ToArray();
        string[] opcodes={"C6","C5","D8","00","C3","CE"};string[] cursors={"59EB","59EE","59F0","59F1","59F2","59F4"};
        if(commands.Length!=6)throw new InvalidDataException("Fresh command count differs");
        for(int i=0;i<commands.Length;i++){
            if(commands[i].GetProperty("opcode").GetString()!=opcodes[i] || commands[i].GetProperty("cursor").GetString()!=cursors[i])
                throw new InvalidDataException($"Fresh command {i} order differs");
            if(i>0 && Convert.ToUInt64(commands[i].GetProperty("cycle").GetString()!,16)<=Convert.ToUInt64(commands[i-1].GetProperty("cycle").GetString()!,16))
                throw new InvalidDataException("Fresh command cycles are not increasing");
        }
        var wait=primary.GetProperty("wait");
        if(wait.GetProperty("cursor").GetString()!="59F6" || wait.GetProperty("duration").GetString()!="FF" || wait.GetProperty("callback").GetString()!="5E29")
            throw new InvalidDataException("Fresh wait contract differs");

        var cancelFull=root.GetProperty("cancel_full");
        if(cancelFull.GetProperty("cycle").GetString()!="000000002B4CA7C0")throw new InvalidDataException("Full cancel occurrence identity differs");
        var fullFrames=cancelFull.GetProperty("frames").EnumerateArray().ToArray();
        var cancelBefore=Find(fullFrames,"cancel-before");var cancelAfter=Find(fullFrames,"cancel-after");
        var lastCancelCaller=ReadFrame(cancelFull.GetProperty("cancel").GetProperty("caller"));
        var returnMarker=ReadFrame(cancelFull.GetProperty("return").GetProperty("marker"));
        if(lastCancelCaller.PC!=0x5C7A || lastCancelCaller.Cycle!=0x2B4CA7C0 || lastCancelCaller.S!=0x079E || lastCancelCaller.A!=0x91 || lastCancelCaller.B!=0x02)
            throw new InvalidDataException("Full cancel caller frame differs");
        if(returnMarker.PC!=0x5A1C || returnMarker.Cycle!=0x2B4CAF49 || returnMarker.S!=0x07A4)
            throw new InvalidDataException("Full return marker differs");

        var regions=root.GetProperty("rom_regions").EnumerateArray().ToArray();
        byte[] Required(ushort address,int length){foreach(var region in regions){int at=region.GetProperty("address").GetInt32();var bytes=Convert.FromHexString(region.GetProperty("bytes_hex").GetString()!);if(address>=at && address+length<=at+bytes.Length)return bytes[(address-at)..(address-at+length)];}throw new InvalidDataException($"Missing required ROM region {address:X4}");}
        byte[] stream=Required(0x59EB,0x20);Required(0x608E,14);Required(0x60AB,19);Required(0x5C18,0x123);Required(0x5E2C,0x61);
        if(!Convert.ToHexString(stream.AsSpan(0,20)).Equals("C659F7C500D800C300CEFFC421313F00FFFF0F0F",StringComparison.Ordinal))
            throw new InvalidDataException("Fresh 59EB stream bytes differ");
        var m=new Machine();
        foreach(var region in regions)Convert.FromHexString(region.GetProperty("bytes_hex").GetString()!).CopyTo(m.Memory,region.GetProperty("address").GetInt32());
        fc4d.Ram.CopyTo(m.Memory,0);
        int deltaCount=0;
        foreach(var delta in primary.GetProperty("foreground_delta").EnumerateArray()){
            int offset=Convert.ToInt32(delta.GetProperty("offset").GetString()!,16);
            byte from=delta.GetProperty("from").GetByte();byte to=delta.GetProperty("to").GetByte();
            if(offset!=0x4D && (offset<0x798 || offset>0x7A9))throw new InvalidDataException($"Foreground delta touches {offset:X3}");
            if(m.Memory[offset]!=from)throw new InvalidDataException($"Foreground delta source differs at {offset:X3}");
            m.Memory[offset]=to;deltaCount++;
        }
        if(deltaCount!=16)throw new InvalidDataException("Fresh foreground delta count differs");

        using(var sound=new AddersNativeSound(m)){
            Host(m,primary.GetProperty("queue").GetProperty("host"),fc4d,"queue");
            ushort queueReturn=Continuation(m,queue,QueueContinuation,"queue");
            ushort queueEnd=0;sound.ObserveInstruction=i=>queueEnd=i.Address;
            sound.BeginCall(0x5C18,0,queue.S,queue.U,queue.X,queue.Y,queue.A,queue.B,false,queueReturn);
            while(sound.Servicing)sound.AdvanceTo(sound.NextEventCycle);
            if(!sound.Active || m.ReadWord(0x47)!=0x1A0 || m.ReadWord(0x49)!=0x1C5)throw new InvalidDataException("Fresh queue did not create the real tone task");
            if(queueEnd!=0x5C4F || sound.CompletedCalls!=1 || sound.LastAddress!=queueReturn)throw new InvalidDataException("Fresh queue did not reach 5C4F and consume the captured 59E9 continuation");
            CompareRetained(m,serviceBefore.Ram,"queue",include4D:true);
        }

        serviceBefore.Ram.CopyTo(m.Memory,0);
        using(var sound=new AddersNativeSound(m)){
            Host(m,primary.GetProperty("service").GetProperty("host"),serviceBefore,"service");
            if(serviceAfter.PC!=ServiceContinuation)throw new InvalidDataException("Fresh service return frame is not FECC");
            if(primary.GetProperty("service").GetProperty("return_word").GetString()!="FECC")throw new InvalidDataException("Fresh service fixture return word differs");
            ushort serviceReturn=Continuation(m,serviceBefore,serviceAfter.PC,"service");
            ushort serviceEnd=0;sound.ObserveInstruction=i=>serviceEnd=i.Address;
            sound.BeginService(0,serviceBefore.S,serviceBefore.U,serviceBefore.X,serviceBefore.Y,false,serviceReturn);
            while(sound.Servicing)sound.AdvanceTo(sound.NextEventCycle);
            CompareRetained(m,serviceAfter.Ram,"service",include4D:true);
            if(serviceEnd!=0x5D3A || sound.CompletedCalls!=1 || sound.LastAddress!=serviceReturn)throw new InvalidDataException("Fresh service did not reach 5D3A and consume the captured FECC continuation");
            if(m.ReadWord((ushort)(0x1A0+8))!=0x59F6 || m.ReadWord((ushort)(0x1A0+2))!=0x3A1B)throw new InvalidDataException("Fresh service did not consume the six natural commands to the CE wait");
        }

        cancelBefore.Ram.CopyTo(m.Memory,0);
        using(var sound=new AddersNativeSound(m)){
            Host(m,cancelFull.GetProperty("cancel").GetProperty("host"),cancelBefore,"cancel");
            if(p10.PC!=CancelContinuation)throw new InvalidDataException("Fresh cancel foreground marker is not 5A10");
            ushort cancelReturn=Continuation(m,lastCancelCaller,CancelContinuation,"cancel");
            ushort cancelEnd=0;sound.ObserveInstruction=i=>cancelEnd=i.Address;
            sound.BeginCall(0x5C7A,0,lastCancelCaller.S,lastCancelCaller.U,lastCancelCaller.X,lastCancelCaller.Y,lastCancelCaller.A,lastCancelCaller.B,false,cancelReturn);
            while(sound.Servicing)sound.AdvanceTo(sound.NextEventCycle);
            if(m.ReadWord(0x47)!=0 || m.ReadWord(0x49)!=0x1A0)throw new InvalidDataException("Fresh cancel did not release the tone owner");
            if(cancelEnd!=0x5C95 || sound.CompletedCalls!=1 || sound.LastAddress!=cancelReturn)throw new InvalidDataException("Fresh cancel did not reach 5C95 and consume the captured 5A10 continuation");
            CompareRetained(m,cancelAfter.Ram,"cancel",include4D:false);
            if(m.Memory[0x4D]!=0x31)throw new InvalidDataException("Native cancel unexpectedly changed the foreground 0x4D input");
        }
        return 3;
    }

    public static int Rejects(string evidence,string kind)
    {
        string original=File.ReadAllText(FilePath(evidence));
        var root=JsonNode.Parse(original)!.AsObject();
        JsonObject Frame(string name){
            var frames=root["primary"]!["frames"]!.AsArray();
            foreach(var item in frames)if(item!["name"]!.GetValue<string>()==name)return item!.AsObject();
            throw new InvalidDataException($"Missing fixture frame {name}");
        }
        if(kind=="hash"){
            var frame=Frame("fc4d");string hex=frame["ram_hex"]!.GetValue<string>();
            string changed=hex.Substring(0,2)=="FF" ? "00" : "FF";
            frame["ram_hex"]=changed+hex.Substring(2);
        }else if(kind=="frame"){
            var frame=Frame("service-after");string hex=frame["ram_hex"]!.GetValue<string>();
            int at=0x1AA*2;string changed=hex.Substring(at,2)=="FF" ? "00" : "FF";
            frame["ram_hex"]=hex.Substring(0,at)+changed+hex.Substring(at+2);
            byte[] ram=Convert.FromHexString(frame["ram_hex"]!.GetValue<string>());
            frame["ram_sha256"]=Convert.ToHexString(SHA256.HashData(ram));
        }else if(kind=="order"){
            root["primary"]!["commands"]!.AsArray()[0]!["opcode"]="C7";
        }else if(kind=="pool" || kind=="link"){
            var frame=Frame("service-after");string hex=frame["ram_hex"]!.GetValue<string>();
            int at=(kind=="pool" ? 0x1C5 : 0x283)*2;
            string changed=hex.Substring(at,2)=="FF" ? "00" : "FF";
            frame["ram_hex"]=hex.Substring(0,at)+changed+hex.Substring(at+2);
            byte[] ram=Convert.FromHexString(frame["ram_hex"]!.GetValue<string>());
            frame["ram_sha256"]=Convert.ToHexString(SHA256.HashData(ram));
        }else if(kind=="continuation"){
            var frame=Frame("service-before");string hex=frame["ram_hex"]!.GetValue<string>();
            int at=Convert.ToUInt16(frame["s"]!.GetValue<string>(),16)*2;
            frame["ram_hex"]=hex.Substring(0,at)+"4C34"+hex.Substring(at+4);
            byte[] ram=Convert.FromHexString(frame["ram_hex"]!.GetValue<string>());
            frame["ram_sha256"]=Convert.ToHexString(SHA256.HashData(ram));
        }else if(kind=="snapshot"){
            var frame=Frame("fc4d");frame["ram_hex"]=frame["ram_hex"]!.GetValue<string>().Substring(0,100);
        }else if(kind=="rom"){
            var regions=root["rom_regions"]!.AsArray();
            var keep=regions.Where(r=>r!["address"]!.GetValue<int>()!=0x608E).Select(r=>r!.DeepClone()).ToArray();
            regions.Clear();foreach(var region in keep)regions.Add(region);
        }else throw new ArgumentOutOfRangeException(nameof(kind));
        string dir=Directory.CreateTempSubdirectory("fruitmachine-fresh-tone-negative-").FullName;
        try{
            Directory.CreateDirectory(Path.Combine(dir,"collection"));
            File.WriteAllText(Path.Combine(dir,"collection","fresh-tone-occurrence.json"),root.ToJsonString());
            bool rejected=false;try{Verify(dir);}catch(Exception error)when(error is InvalidDataException or NotSupportedException){rejected=true;}
            if(!rejected)throw new InvalidDataException($"Fresh tone negative {kind} was accepted");
        }finally{Directory.Delete(dir,true);}
        return 1;
    }
}
